// Status badge registry (FE-017): every status value from the shared vocabulary (CT-21,
// status-vocabulary.json, generated by the backend) gets one badge tone, so a status looks the
// same on every page. Labels live in i18n under status.<VALUE>.
import vocabulary from './status-vocabulary.json'

const TONE_GROUPS = {
  // Finished well
  success: [
    'ACCEPTED',
    'ACKNOWLEDGED',
    'ACTIVE',
    'AVAILABLE',
    'CHAMPION',
    'COMPLETED',
    'CONFIRMED',
    'CONSUMED',
    'DONE',
    'EXPORTED_TO_TOS',
    'FULL',
    'OPTIMAL',
    'PARSED',
    'PROMOTED',
    'SUCCESS',
    'YARD_REC_ACCEPTED',
  ],
  // Under way
  info: [
    'ADJUSTED',
    'ASSIGNED',
    'BUSY',
    'CHALLENGER',
    'CUSTOMS_APPROVED',
    'ENTRY_WINDOW_CONFIRMED',
    'FEASIBLE',
    'KEPT_CHAMPION',
    'MODIFIED_BY_STAFF',
    'ONBOARDING',
    'PENDING',
    'PENDING_REVIEW',
    'PLAN_CONFIRMED',
    'PRELIMINARY_APPROVED',
    'PROPOSED',
    'QUEUED',
    'RECOMMENDATION_GENERATED',
    'RESERVED',
    'RUNNING',
    'SETUP',
    'STAGED',
    'STARTED',
    'SUBMITTED',
    'YARD_REC_GENERATED',
    'YARD_REC_REQUESTED',
  ],
  // Needs someone's attention
  warning: [
    'BLOCKED',
    'MAINTENANCE',
    'NEEDS_REVISION',
    'QUARANTINED',
    'READ_ONLY',
    'SUSPENDED',
    'UNASSIGNED',
  ],
  // Failed or refused
  danger: [
    'ERROR',
    'EXPIRED',
    'FAILED',
    'GENERATION_FAILED',
    'INFEASIBLE',
    'REJECTED',
    'REVOKED',
    'YARD_REC_REJECTED',
  ],
  // Ended without going ahead, or out of use
  neutral: [
    'ARCHIVED',
    'CANCELLED',
    'INACTIVE',
    'INVALIDATED',
    'OFFBOARDED',
    'PLAN_CANCELLED',
    'RELEASED',
    'REPLACED',
    'SENT',
    'WITHDRAWN',
  ],
}

export const STATUS_TONES = Object.freeze(
  Object.fromEntries(
    Object.entries(TONE_GROUPS).flatMap(([tone, values]) => values.map((v) => [v, tone])),
  ),
)

export const statusTone = (value) => STATUS_TONES[value] ?? 'neutral'

// Vocabulary columns that hold a state shown as a badge (units, types and sources are not).
export const STATUS_COLUMN = /\.(\w*status|\w*state|decision|mode)$/

export function statusColumns() {
  const all = { ...vocabulary.columns, ...vocabulary.derived }
  return Object.fromEntries(Object.entries(all).filter(([column]) => STATUS_COLUMN.test(column)))
}
